INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (401, 0, 2, "2030/12/17 14:59:59", "アヤネ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 102301, 24001, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (402, 2.21, 2, "2030/12/17 14:59:59", "アヤネ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 102301, 24002, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (403, 0, 2, "2030/12/17 14:59:59", "アヤネ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 102301, 24003, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (701, 1.99, 1, "2030/12/17 14:59:59", "アサヒ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192201, 24004, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (702, 2.21, 2, "2030/12/17 14:59:59", "アサヒ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192201, 24005, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (703, 3.33, 1, "2030/12/17 14:59:59", "アサヒ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192201, 24006, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (801, 0, 2, "2030/12/17 14:59:59", "部員３", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192301, 24007, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (802, 2.68, 2, "2030/12/17 14:59:59", "部員３", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192301, 24008, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (803, 0, 2, "2030/12/17 14:59:59", "部員３", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192301, 24009, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (501, 0, 1, "2030/12/17 14:59:59", "", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192501, 24010, "やった！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (502, 0, 1, "2030/12/17 14:59:59", "", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192501, 24011, "勝ったよ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (503, 0, 1, "2030/12/17 14:59:59", "", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192501, 24012, "いい調子！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (111, 5.33, 2, "2030/12/17 14:59:59", "ミサト", 0, 10046, "2020/07/31 12:00:00", 6, 24, 113501, 24013, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (112, 6.85, 2, "2030/12/17 14:59:59", "ミサト", 0, 10046, "2020/07/31 12:00:00", 1, 24, 113501, 24014, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (113, 3, 2, "2030/12/17 14:59:59", "ミサト", 0, 10046, "2020/07/31 12:00:00", 1, 24, 113501, 24015, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (611, 6.11, 2, "2030/12/17 14:59:59", "ダイチ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192401, 24016, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (612, 6.75, 2, "2030/12/17 14:59:59", "ダイチ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192401, 24017, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (613, 0, 2, "2030/12/17 14:59:59", "ダイチ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192401, 24018, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (211, 4.52, 1, "2030/12/17 14:59:59", "ハツネ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 113401, 24019, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (212, 3.89, 1, "2030/12/17 14:59:59", "ハツネ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 113401, 24020, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (213, 13.49, 2, "2030/12/17 14:59:59", "ハツネ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 113401, 24021, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (311, 3.17, 2, "2030/12/17 14:59:59", "カヤ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 106501, 24022, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (312, 4.42, 2, "2030/12/17 14:59:59", "カヤ", 0, 10046, "2020/07/31 12:00:00", 1, 24, 106501, 24023, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (313, 2.89, 1, "2030/12/17 14:59:59", "カヤ", 0, 10046, "2020/07/31 12:00:00", 6, 24, 106501, 24024, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (421, 3.71, 3, "2030/12/17 14:59:59", "アヤネ", 0, 10046, "2020/07/31 12:00:00", 4, 24, 102301, 24025, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (721, 5.1, 1, "2030/12/17 14:59:59", "アサヒ", 0, 10046, "2020/07/31 12:00:00", 2, 24, 192201, 24026, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (821, 4.34, 3, "2030/12/17 14:59:59", "部員３", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192301, 24027, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (521, 0, 1, "2030/12/17 14:59:59", "", 0, 10046, "2020/07/31 12:00:00", 1, 24, 192501, 24028, "いい勝負だったよ\nまたやろうね", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (101, 5.62, 2, "2030/12/17 14:59:59", "ミサト", -360, 10046, "2020/07/31 12:00:00", 1, 24, 113501, 24029, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (102, 9.58, 2, "2030/12/17 14:59:59", "ミサト", -360, 10046, "2020/07/31 12:00:00", 1, 24, 113501, 24030, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (103, 0, 2, "2030/12/17 14:59:59", "ミサト", -360, 10046, "2020/07/31 12:00:00", 2, 24, 113501, 24031, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (104, 9.13, 1, "2030/12/17 14:59:59", "ミサト", -360, 10046, "2020/07/31 12:00:00", 2, 24, 113501, 24032, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (105, 8.27, 2, "2030/12/17 14:59:59", "ミサト", -360, 10046, "2020/07/31 12:00:00", 1, 24, 113501, 24033, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 0);
